cenozoApp.extendModule({name:"root",dependencies:["apex_review","review"],create:module=>{var apexReviewModule=cenozoApp.module("apex_review");var reviewModule=cenozoApp.module("review");cenozo.providers.decorator("cnHomeDirective",["$delegate","$compile","CnSession","CnApexReviewModelFactory","CnReviewModelFactory",function($delegate,$compile,CnSession,CnApexReviewModelFactory,CnReviewModelFactory){var oldController=$delegate[0].controller;var oldLink=$delegate[0].link;if(["coordinator","typist"].includes(CnSession.role.name)){angular.extend($delegate[0],{compile:function(){return function(scope,element,attrs){if(angular.isFunction(oldLink))oldLink(scope,element,attrs);const el=angular.element(element[0].querySelector(".inner-view-frame div"));el.append(CnSession.user.apexUser?'<cn-apex-review-list model="reviewModel"></cn-apex-review-list>':'<cn-review-list model="reviewModel"></cn-review-list>');$compile(element.contents())(scope)}},controller:function($scope){oldController($scope);$scope.reviewModel=CnSession.user.apexUser?CnApexReviewModelFactory.instance():CnReviewModelFactory.instance();$scope.reviewModel.listModel.heading="Outstanding Review List"}})}return $delegate}])}});
